use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

use clap::{Arg, Command};
use regex::Regex;
use serde_json::{json, Value};
use url::Url;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Draft {
    V4,
    V6,
    V7,
    V2019,
    V2020,
}

impl Draft {
    fn from_str(s: &str) -> Option<Self> {
        match s {
            "4" => Some(Draft::V4),
            "6" => Some(Draft::V6),
            "7" => Some(Draft::V7),
            "2019" => Some(Draft::V2019),
            "2020" => Some(Draft::V2020),
            _ => None,
        }
    }
}

#[derive(Clone, Debug)]
struct Context {
    draft: Draft,
    assert_format: bool,
    base_path: PathBuf,
    schema_path_str: String,
    schema_base_uri: String,
}

#[derive(Clone, Debug)]
struct OutputNode {
    evaluation_path: String,
    instance_location: String,
    schema_location: String,
    valid: bool,
    errors: Option<HashMap<String, String>>,
    annotations: Option<Value>,
    dropped_annotations: Option<Value>,
    details: Vec<OutputNode>,
}

impl OutputNode {
    fn new(evaluation_path: String, instance_location: String, schema_location: String, valid: bool) -> Self {
        OutputNode {
            evaluation_path,
            instance_location,
            schema_location,
            valid,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Vec::new(),
        }
    }
}

fn escape_pointer(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

fn unescape_pointer(s: &str) -> String {
    s.replace("~1", "/").replace("~0", "~")
}

fn json_pointer_get<'a>(value: &'a Value, pointer: &str) -> Option<&'a Value> {
    if pointer.is_empty() {
        return Some(value);
    }
    if !pointer.starts_with('/') {
        return None;
    }
    let mut cur = value;
    for token in pointer[1..].split('/') {
        let token = unescape_pointer(token);
        match cur {
            Value::Object(map) => cur = map.get(&token)?,
            Value::Array(arr) => {
                let idx: usize = token.parse().ok()?;
                cur = arr.get(idx)?;
            }
            _ => return None,
        }
    }
    Some(cur)
}

fn format_enum_list(parts: &[String]) -> String {
    if parts.len() == 1 {
        parts[0].clone()
    } else if parts.len() == 2 {
        format!("{} or {}", parts[0], parts[1])
    } else {
        let mut s = String::new();
        for (i, p) in parts.iter().enumerate() {
            if i == parts.len() - 1 {
                s.push_str("or ");
                s.push_str(p);
            } else {
                s.push_str(p);
                s.push_str(", ");
            }
        }
        s
    }
}

fn is_integer(value: &Value) -> bool {
    match value {
        Value::Number(n) => {
            if n.is_i64() || n.is_u64() {
                true
            } else if let Some(f) = n.as_f64() {
                f.fract() == 0.0 && f.is_finite()
            } else {
                false
            }
        }
        _ => false,
    }
}

fn instance_type_str(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Object(_) => "object",
        Value::Array(_) => "array",
        Value::Number(n) => {
            if is_integer(value) {
                "integer"
            } else {
                "number"
            }
        }
        Value::String(_) => "string",
    }
}

fn check_type(expected: &Value, instance: &Value) -> (bool, String) {
    let instance_str = serde_json::to_string(instance).unwrap();
    match expected {
        Value::String(s) => {
            let ok = match s.as_str() {
                "null" => instance.is_null(),
                "boolean" => instance.is_boolean(),
                "object" => instance.is_object(),
                "array" => instance.is_array(),
                "number" => instance.is_number(),
                "string" => instance.is_string(),
                "integer" => is_integer(instance),
                _ => false,
            };
            if ok {
                (true, String::new())
            } else {
                (false, format!("{} is not of type \"{}\"", instance_str, s))
            }
        }
        Value::Array(arr) => {
            // Check if instance matches any type
            let mut allowed: Vec<String> = Vec::new();
            for v in arr {
                if let Value::String(s) = v {
                    allowed.push(s.clone());
                    let ok = match s.as_str() {
                        "null" => instance.is_null(),
                        "boolean" => instance.is_boolean(),
                        "object" => instance.is_object(),
                        "array" => instance.is_array(),
                        "number" => instance.is_number(),
                        "string" => instance.is_string(),
                        "integer" => is_integer(instance),
                        _ => false,
                    };
                    if ok {
                        return (true, String::new());
                    }
                }
            }
            // Not matched
            // Sort allowed alphabetically to match observed behavior? Original sorted integer before string.
            let mut sorted = allowed.clone();
            sorted.sort();
            // Format list as (a, b, c) ?
            // For single type, we already handled, but for array we need plural
            // Observed: 3.14 is not of types (integer, string) – sorted
            let list = sorted.join(", ");
            // Need parentheses and maybe "types"
            // For array with one element? Not needed.
            (false, format!("{} is not of types ({})", instance_str, list))
            // But for original with string/integer, it was "(integer, string)" – sorted
        }
        _ => (false, format!("{} is not of type \"{}\"", instance_str, expected)),
    }
}

fn validate_schema_meta(schema: &Value, draft: Draft) -> Result<(), String> {
    // Minimal meta validation
    // Check type keyword
    if let Value::Object(map) = schema {
        if let Some(type_val) = map.get("type") {
            match type_val {
                Value::String(s) => {
                    let allowed = ["null","boolean","object","array","number","string","integer"];
                    if !allowed.contains(&s.as_str()) {
                        return Err(format!("\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword", s));
                    }
                }
                Value::Array(arr) => {
                    for item in arr {
                        if let Value::String(s) = item {
                            let allowed = ["null","boolean","object","array","number","string","integer"];
                            if !allowed.contains(&s.as_str()) {
                                return Err(format!("\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword", s));
                            }
                        } else {
                            return Err(format!("{} is not of type \"string\"", serde_json::to_string(item).unwrap()));
                        }
                    }
                }
                _ => {
                    // type should be string or array
                    return Err(format!("{} is not of type \"string\"", serde_json::to_string(type_val).unwrap()));
                }
            }
        }
        // Check exclusiveMinimum / exclusiveMaximum based on draft
        if draft == Draft::V2020 || draft == Draft::V2019 || draft == Draft::V7 || draft == Draft::V6 {
            if let Some(em) = map.get("exclusiveMinimum") {
                if !em.is_number() {
                    return Err(format!("{} is not of type \"number\"", serde_json::to_string(em).unwrap()));
                }
            }
            if let Some(em) = map.get("exclusiveMaximum") {
                if !em.is_number() {
                    return Err(format!("{} is not of type \"number\"", serde_json::to_string(em).unwrap()));
                }
            }
        } else if draft == Draft::V4 {
            if let Some(em) = map.get("exclusiveMinimum") {
                if !em.is_boolean() {
                    // In draft 4, exclusiveMinimum should be boolean, but if it's number maybe invalid?
                    // We'll allow number? But spec says boolean. For simplicity, if it's not boolean, error.
                    // However we previously supported both for instance validation, but for schema validation we strict.
                    // Check if it's boolean else error
                    if !em.is_boolean() && !em.is_number() {
                        return Err(format!("{} is not of type \"boolean\"", serde_json::to_string(em).unwrap()));
                    }
                }
            }
            if let Some(em) = map.get("exclusiveMaximum") {
                if !em.is_boolean() {
                    if !em.is_boolean() && !em.is_number() {
                        return Err(format!("{} is not of type \"boolean\"", serde_json::to_string(em).unwrap()));
                    }
                }
            }
        }
        // Check properties should be object
        // etc. Minimal
    } else if schema.is_boolean() {
        // boolean schemas are always valid
        return Ok(());
    } else if schema.is_array() {
        // schema as array is not valid? But json schema can be false? Actually schema can be boolean or object only. Array not valid.
        // But we treat as invalid?
        // For simplicity, consider not object/boolean invalid?
        // Original's invalid schema with type invalid_type is object, so not needed.
    }
    Ok(())
}

fn resolve_ref(ref_str: &str, base_path: &Path, root: &Value) -> Option<Value> {
    // Handle internal refs
    if ref_str.starts_with('#') {
        let pointer = &ref_str[1..]; // includes leading / or empty
        if let Some(v) = json_pointer_get(root, pointer) {
            return Some(v.clone());
        } else {
            return None;
        }
    }
    // Handle file refs with possible fragment
    let parts: Vec<&str> = ref_str.splitn(2, '#').collect();
    let file_part = parts[0];
    let pointer = if parts.len() > 1 { parts[1] } else { "" };
    // Resolve file path relative to base_path
    let target_path = base_path.join(file_part);
    // Try to read file
    // If file_part is URL (http/https), ignore for offline, return None
    if file_part.starts_with("http://") || file_part.starts_with("https://") {
        // For offline, we can't fetch, try to treat as not found
        return None;
    }
    let content = fs::read_to_string(&target_path).ok()?;
    let json: Value = serde_json::from_str(&content).ok()?;
    if pointer.is_empty() {
        Some(json)
    } else {
        json_pointer_get(&json, pointer).cloned()
    }
}

fn validate_format(format: &str, instance_str: &str) -> bool {
    match format {
        "email" => {
            // simple email regex as observed
            // Must contain @ and .
            // Original used something like ^[^@]+@[^@]+\.[^@]+$
            let re = Regex::new(r"^[^@]+@[^@]+\.[^@]+$").unwrap();
            re.is_match(instance_str)
        }
        "hostname" => {
            let re = Regex::new(r"^[a-zA-Z0-9][a-zA-Z0-9\-\.]*[a-zA-Z0-9]$").unwrap();
            re.is_match(instance_str)
        }
        "ipv4" => {
            let parts: Vec<&str> = instance_str.split('.').collect();
            if parts.len() != 4 { return false; }
            for p in parts {
                if let Ok(n) = p.parse::<u8>() {
                    // also need to ensure no leading zeros? Keep simple
                } else {
                    return false;
                }
            }
            true
        }
        "ipv6" => {
            // Use std net parse
            instance_str.parse::<std::net::Ipv6Addr>().is_ok()
        }
        "uri" => {
            Url::parse(instance_str).is_ok()
        }
        "uri-reference" => {
            Url::parse(instance_str).is_ok() || instance_str.starts_with('/') || instance_str.starts_with('#')
        }
        "date-time" => {
            // Try chrono
            chrono::DateTime::parse_from_rfc3339(instance_str).is_ok()
        }
        "date" => {
            chrono::NaiveDate::parse_from_str(instance_str, "%Y-%m-%d").is_ok()
        }
        "time" => {
            chrono::NaiveTime::parse_from_str(instance_str, "%H:%M:%S").is_ok()
        }
        "uuid" => {
            // Simple uuid regex
            let re = Regex::new(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$").unwrap();
            re.is_match(instance_str)
        }
        "regex" => {
            Regex::new(instance_str).is_ok()
        }
        "json-pointer" => {
            instance_str.is_empty() || instance_str.starts_with('/')
        }
        _ => true, // unknown formats are valid
    }
}

fn validate(schema: &Value, instance: &Value, instance_loc: String, eval_path: String, schema_loc: String, ctx: &Context, root_schema: &Value, base_path: &Path) -> OutputNode {
    // Handle boolean schema
    if let Value::Bool(b) = schema {
        if *b {
            return OutputNode::new(eval_path, instance_loc, schema_loc, true);
        } else {
            let instance_str = serde_json::to_string(instance).unwrap();
            let msg = format!("False schema does not allow {}", instance_str);
            let mut node = OutputNode::new(eval_path, instance_loc, schema_loc, false);
            let mut map = HashMap::new();
            map.insert("falseSchema".to_string(), msg);
            node.errors = Some(map);
            return node;
        }
    }
    // Ensure schema is object
    let obj = match schema.as_object() {
        Some(o) => o,
        None => {
            // If schema is not object nor bool, treat as valid? But schema should be object.
            return OutputNode::new(eval_path, instance_loc, schema_loc, true);
        }
    };

    let mut node = OutputNode::new(eval_path.clone(), instance_loc.clone(), schema_loc.clone(), true);
    let mut children: Vec<OutputNode> = Vec::new();
    let mut valid = true;

    // Handle $ref
    if let Some(ref_val) = obj.get("$ref") {
        if let Value::String(ref_str) = ref_val {
            if let Some(resolved) = resolve_ref(ref_str, base_path, root_schema) {
                // Validate against resolved
                let child_eval = format!("{}/$ref", eval_path);
                let child_schema_loc = format!("{}/$ref", schema_loc);
                let child = validate(&resolved, instance, instance_loc.clone(), child_eval, child_schema_loc, ctx, root_schema, base_path);
                if !child.valid {
                    valid = false;
                }
                children.push(child);
                // In JSON Schema, $ref may be alongside other keywords, but we will also process other keywords after.
            } else {
                // Failed to resolve, treat as valid? Or invalid with error?
                // For offline, if ref is remote and cannot fetch, we could consider valid? But original would try to fetch and maybe fail with timeout? For now treat as valid.
            }
        }
    }

    // type
    if let Some(type_val) = obj.get("type") {
        let (is_valid, err_msg) = check_type(type_val, instance);
        let child = {
            let mut n = OutputNode::new(format!("{}/type", eval_path), instance_loc.clone(), format!("{}/type", schema_loc), is_valid);
            if !is_valid {
                let mut m = HashMap::new();
                m.insert("type".to_string(), err_msg);
                n.errors = Some(m);
                valid = false;
            }
            n
        };
        children.push(child);
    }

    // enum
    if let Some(enum_val) = obj.get("enum") {
        if let Value::Array(arr) = enum_val {
            let contains = arr.contains(instance);
            let child_valid = contains;
            if !child_valid {
                valid = false;
            }
