        } else if let Some(items) = obj.get("items") {
            match items {
                Value::Object(_) | Value::Bool(_) => {
                    // items as schema (draft 4) – applies to all items
                    for (i, val) in arr.iter().enumerate() {
                        let child_loc = format!("{}/{}", instance_loc, i);
                        let child_eval = format!("{}/items", eval_path);
                        let child_schema_loc = format!("{}/items", schema_loc);
                        let child = validate(items, val, child_loc, child_eval, child_schema_loc, ctx, root_schema, base_path);
                        if !child.valid {
                            valid = false;
                        }
                        children.push(child);
                    }
                }
                Value::Array(item_arr) => {
                    // items as array (draft 4 tuple)
                    for (i, sub_schema) in item_arr.iter().enumerate() {
                        if i < arr.len() {
                            let val = &arr[i];
                            let child_loc = format!("{}/{}", instance_loc, i);
                            let child_eval = format!("{}/items/{}", eval_path, i);
                            let child_schema_loc = format!("{}/items/{}", schema_loc, i);
                            let child = validate(sub_schema, val, child_loc, child_eval, child_schema_loc, ctx, root_schema, base_path);
                            if !child.valid {
                                valid = false;
                            }
                            children.push(child);
                        }
                    }
                    // additionalItems handling?
                    if let Some(add_items) = obj.get("additionalItems") {
                        match add_items {
                            Value::Bool(b) => {
                                if !b && arr.len() > item_arr.len() {
                                    valid = false;
                                    // For simplicity, create error for extra items
                                    let msg = format!("Additional items are not allowed ({})", arr.len() - item_arr.len());
                                    let mut child = OutputNode::new(format!("{}/additionalItems", eval_path), instance_loc.clone(), format!("{}/additionalItems", schema_loc), false);
                                    let mut m = HashMap::new();
                                    m.insert("additionalItems".to_string(), msg);
                                    child.errors = Some(m);
                                    children.push(child);
                                }
                            }
                            _ => {
                                for i in item_arr.len()..arr.len() {
                                    let val = &arr[i];
                                    let child_loc = format!("{}/{}", instance_loc, i);
                                    let child_eval = format!("{}/additionalItems", eval_path);
                                    let child_schema_loc = format!("{}/additionalItems", schema_loc);
                                    let child = validate(add_items, val, child_loc, child_eval, child_schema_loc, ctx, root_schema, base_path);
                                    if !child.valid {
                                        valid = false;
                                    }
                                    children.push(child);
                                }
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        // contains
        if let Some(contains) = obj.get("contains") {
            let mut found = false;
            let mut contain_children = Vec::new();
            for (i, val) in arr.iter().enumerate() {
                let child_loc = format!("{}/{}", instance_loc, i);
                let child_eval = format!("{}/contains", eval_path);
                let child_schema_loc = format!("{}/contains", schema_loc);
                let child = validate(contains, val, child_loc, child_eval, child_schema_loc, ctx, root_schema, base_path);
                if child.valid {
                    found = true;
                }
                contain_children.push(child);
            }
            let is_valid = found || arr.is_empty() && false; // empty array fails contains? According spec, empty fails.
            // Actually for contains, empty array should be invalid because no element matches.
            let child_valid = found;
            if !child_valid {
                valid = false;
            }
            let mut child = OutputNode::new(format!("{}/contains", eval_path), instance_loc.clone(), format!("{}/contains", schema_loc), child_valid);
            if !child_valid {
                let instance_str = serde_json::to_string(instance).unwrap();
                let msg = format!("None of {} are valid under the given schema", instance_str);
                let mut m = HashMap::new();
                m.insert("contains".to_string(), msg);
                child.errors = Some(m);
            }
            // Optionally add details of each element? But for simplicity, not.
            children.push(child);
        }
        // minItems / maxItems
        if let Some(min_items) = obj.get("minItems") {
            if let Some(n) = min_items.as_u64() {
                let len = arr.len() as u64;
                if len < n {
                    valid = false;
                    let instance_str = serde_json::to_string(instance).unwrap();
                    let msg = format!("{} has less than {} items", instance_str, n);
                    let mut child = OutputNode::new(format!("{}/minItems", eval_path), instance_loc.clone(), format!("{}/minItems", schema_loc), false);
                    let mut m = HashMap::new();
                    m.insert("minItems".to_string(), msg);
                    child.errors = Some(m);
                    children.push(child);
                } else {
                    let child = OutputNode::new(format!("{}/minItems", eval_path), instance_loc.clone(), format!("{}/minItems", schema_loc), true);
                    children.push(child);
                }
            }
        }
        if let Some(max_items) = obj.get("maxItems") {
            if let Some(n) = max_items.as_u64() {
                let len = arr.len() as u64;
                if len > n {
                    valid = false;
                    let instance_str = serde_json::to_string(instance).unwrap();
                    let msg = format!("{} has more than {} items", instance_str, n);
                    let mut child = OutputNode::new(format!("{}/maxItems", eval_path), instance_loc.clone(), format!("{}/maxItems", schema_loc), false);
                    let mut m = HashMap::new();
                    m.insert("maxItems".to_string(), msg);
                    child.errors = Some(m);
                    children.push(child);
                } else {
                    let child = OutputNode::new(format!("{}/maxItems", eval_path), instance_loc.clone(), format!("{}/maxItems", schema_loc), true);
                    children.push(child);
                }
            }
        }
        // uniqueItems
        if let Some(unique) = obj.get("uniqueItems") {
            if unique.as_bool().unwrap_or(false) {
                let mut seen = std::collections::HashSet::new();
                let mut is_unique = true;
                for val in arr {
                    let s = serde_json::to_string(val).unwrap();
                    if !seen.insert(s) {
                        is_unique = false;
                        break;
                    }
                }
                if !is_unique {
                    valid = false;
                    let instance_str = serde_json::to_string(instance).unwrap();
                    let msg = format!("{} has non-unique elements", instance_str);
                    let mut child = OutputNode::new(format!("{}/uniqueItems", eval_path), instance_loc.clone(), format!("{}/uniqueItems", schema_loc), false);
                    let mut m = HashMap::new();
                    m.insert("uniqueItems".to_string(), msg);
                    child.errors = Some(m);
                    children.push(child);
                } else {
                    let child = OutputNode::new(format!("{}/uniqueItems", eval_path), instance_loc.clone(), format!("{}/uniqueItems", schema_loc), true);
                    children.push(child);
                }
            }
        }
    }

    // String handling
    if instance.is_string() {
        let s = instance.as_str().unwrap();
        if let Some(min_len) = obj.get("minLength") {
            if let Some(n) = min_len.as_u64() {
                let len = s.chars().count() as u64;
                if len < n {
                    valid = false;
                    let instance_str = serde_json::to_string(instance).unwrap();
                    let msg = format!("{} is shorter than {} characters", instance_str, n);
                    let mut child = OutputNode::new(format!("{}/minLength", eval_path), instance_loc.clone(), format!("{}/minLength", schema_loc), false);
                    let mut m = HashMap::new();
                    m.insert("minLength".to_string(), msg);
                    child.errors = Some(m);
                    children.push(child);
                } else {
                    let child = OutputNode::new(format!("{}/minLength", eval_path), instance_loc.clone(), format!("{}/minLength", schema_loc), true);
                    children.push(child);
                }
            }
        }
        if let Some(max_len) = obj.get("maxLength") {
            if let Some(n) = max_len.as_u64() {
                let len = s.chars().count() as u64;
                if len > n {
                    valid = false;
                    let instance_str = serde_json::to_string(instance).unwrap();
                    let msg = format!("{} is longer than {} characters", instance_str, n);
                    let mut child = OutputNode::new(format!("{}/maxLength", eval_path), instance_loc.clone(), format!("{}/maxLength", schema_loc), false);
                    let mut m = HashMap::new();
                    m.insert("maxLength".to_string(), msg);
                    child.errors = Some(m);
                    children.push(child);
                } else {
                    let child = OutputNode::new(format!("{}/maxLength", eval_path), instance_loc.clone(), format!("{}/maxLength", schema_loc), true);
                    children.push(child);
                }
            }
        }
        if let Some(pattern) = obj.get("pattern") {
            if let Value::String(pat) = pattern {
                match Regex::new(pat) {
                    Ok(re) => {
                        if !re.is_match(s) {
                            valid = false;
                            let instance_str = serde_json::to_string(instance).unwrap();
                            let msg = format!("{} does not match \"{}\"", instance_str, pat);
                            let mut child = OutputNode::new(format!("{}/pattern", eval_path), instance_loc.clone(), format!("{}/pattern", schema_loc), false);
                            let mut m = HashMap::new();
                            m.insert("pattern".to_string(), msg);
                            child.errors = Some(m);
                            children.push(child);
                        } else {
                            let child = OutputNode::new(format!("{}/pattern", eval_path), instance_loc.clone(), format!("{}/pattern", schema_loc), true);
                            children.push(child);
                        }
                    }
                    Err(_) => {
                        // invalid regex consider schema invalid? For instance validation, treat as valid? But we already schema validated.
                    }
                }
            }
        }
        // format
        if let Some(fmt) = obj.get("format") {
            if let Value::String(fmt_str) = fmt {
                if ctx.assert_format {
                    // only validate if format is known? Unknown formats are valid
                    let known = ["email","idn-email","hostname","idn-hostname","ipv4","ipv6","uri","uri-reference","iri","iri-reference","uri-template","json-pointer","relative-json-pointer","regex","date","date-time","time","uuid"];
                    if known.contains(&fmt_str.as_str()) {
                        let is_valid = validate_format(fmt_str, s);
                        if !is_valid {
                            valid = false;
                            let instance_str = serde_json::to_string(instance).unwrap();
                            let msg = format!("{} is not a \"{}\"", instance_str, fmt_str);
                            let mut child = OutputNode::new(format!("{}/format", eval_path), instance_loc.clone(), format!("{}/format", schema_loc), false);
                            let mut m = HashMap::new();
                            m.insert("format".to_string(), msg);
                            child.errors = Some(m);
                            children.push(child);
                        } else {
                            let child = OutputNode::new(format!("{}/format", eval_path), instance_loc.clone(), format!("{}/format", schema_loc), true);
                            children.push(child);
                        }
                    } else {
                        // unknown format, consider valid
                        let child = OutputNode::new(format!("{}/format", eval_path), instance_loc.clone(), format!("{}/format", schema_loc), true);
                        children.push(child);
                    }
                }
            }
        }
    }

    // Number handling
    if instance.is_number() {
        let instance_num = instance.as_f64().unwrap_or(0.0);
        // For integer type we already handled type, but need to check numeric keywords only if instance is number
        if let Some(min) = obj.get("minimum") {
            if let Some(min_f) = min.as_f64() {
                if instance_num < min_f {
                    valid = false;
                    let instance_str = serde_json::to_string(instance).unwrap();
                    let msg = format!("{} is less than the minimum of {}", instance_str, min);
                    let mut child = OutputNode::new(format!("{}/minimum", eval_path), instance_loc.clone(), format!("{}/minimum", schema_loc), false);
                    let mut m = HashMap::new();
                    m.insert("minimum".to_string(), msg);
                    child.errors = Some(m);
                    children.push(child);
                } else {
                    let child = OutputNode::new(format!("{}/minimum", eval_path), instance_loc.clone(), format!("{}/minimum", schema_loc), true);
                    children.push(child);
                }
            }
        }
        if let Some(max) = obj.get("maximum") {
            if let Some(max_f) = max.as_f64() {
                if instance_num > max_f {
                    valid = false;
                    let instance_str = serde_json::to_string(instance).unwrap();
                    let msg = format!("{} is greater than the maximum of {}", instance_str, max);
                    let mut child = OutputNode::new(format!("{}/maximum", eval_path), instance_loc.clone(), format!("{}/maximum", schema_loc), false);
                    let mut m = HashMap::new();
                    m.insert("maximum".to_string(), msg);
                    child.errors = Some(m);
                    children.push(child);
                } else {
                    let child = OutputNode::new(format!("{}/maximum", eval_path), instance_loc.clone(), format!("{}/maximum", schema_loc), true);
                    children.push(child);
                }
            }
        }
        // exclusiveMinimum / exclusiveMaximum handling based on draft
        if let Some(ex_min) = obj.get("exclusiveMinimum") {
            match ex_min {
                Value::Bool(b) => {
                    // draft 4 style: exclusiveMinimum is bool, and minimum is also present
                    if *b {
                        if let Some(min) = obj.get("minimum") {
                            if let Some(min_f) = min.as_f64() {
                                if instance_num <= min_f {
                                    valid = false;
                                    let instance_str = serde_json::to_string(instance).unwrap();
                                    let msg = format!("{} is less than or equal to the minimum of {}", instance_str, min);
                                    let mut child = OutputNode::new(format!("{}/exclusiveMinimum", eval_path), instance_loc.clone(), format!("{}/exclusiveMinimum", schema_loc), false);
                                    // In original list, error was at /exclusiveMinimum? Actually for draft 4, error message was at exclusiveMinimum? Let's see earlier: for draft 4 exclusiveMinimum true with minimum 5 and instance 5, error was "5 is less than or equal to the minimum of 5" at evaluationPath maybe /exclusiveMinimum? But earlier we saw text error for draft 4 case was "5 is less than or equal to the minimum of 5" – that suggests exclusiveMinimum handling produced that message at minimum level? For our case, we'll produce error at exclusiveMinimum with that message, but original's text for draft 4 case gave same message without specifying keyword. Our child errors map key is exclusiveMinimum, but message matches.
                                    let mut m = HashMap::new();
                                    m.insert("exclusiveMinimum".to_string(), msg);
                                    child.errors = Some(m);
                                    children.push(child);
                                } else {
                                    let child = OutputNode::new(format!("{}/exclusiveMinimum", eval_path), instance_loc.clone(), format!("{}/exclusiveMinimum", schema_loc), true);
                                    children.push(child);
                                }
                            }
                        }
                    } else {
                        // exclusiveMinimum false means not exclusive, so no check
                        let child = OutputNode::new(format!("{}/exclusiveMinimum", eval_path), instance_loc.clone(), format!("{}/exclusiveMinimum", schema_loc), true);
                        children.push(child);
                    }
                }
                Value::Number(n) => {
                    // draft 2020 style: exclusiveMinimum is number, instance must be > it
                    if let Some(n_f) = n.as_f64() {
                        if instance_num <= n_f {
                            valid = false;
                            let instance_str = serde_json::to_string(instance).unwrap();
                            let msg = format!("{} is less than or equal to the minimum of {}", instance_str, n);
                            let mut child = OutputNode::new(format!("{}/exclusiveMinimum", eval_path), instance_loc.clone(), format!("{}/exclusiveMinimum", schema_loc), false);
                            let mut m = HashMap::new();
                            m.insert("exclusiveMinimum".to_string(), msg);
                            child.errors = Some(m);
                            children.push(child);
                        } else {
                            let child = OutputNode::new(format!("{}/exclusiveMinimum", eval_path), instance_loc.clone(), format!("{}/exclusiveMinimum", schema_loc), true);
                            children.push(child);
                        }
                    }
                }
                _ => {}
            }
        }
        if let Some(ex_max) = obj.get("exclusiveMaximum") {
            match ex_max {
                Value::Bool(b) => {
                    if *b {
                        if let Some(max) = obj.get("maximum") {
                            if let Some(max_f) = max.as_f64() {
                                if instance_num >= max_f {
                                    valid = false;
                                    let instance_str = serde_json::to_string(instance).unwrap();
                                    let msg = format!("{} is greater than or equal to the maximum of {}", instance_str, max);
                                    let mut child = OutputNode::new(format!("{}/exclusiveMaximum", eval_path), instance_loc.clone(), format!("{}/exclusiveMaximum", schema_loc), false);
                                    let mut m = HashMap::new();
                                    m.insert("exclusiveMaximum".to_string(), msg);
                                    child.errors = Some(m);
                                    children.push(child);
                                } else {
                                    let child = OutputNode::new(format!("{}/exclusiveMaximum", eval_path), instance_loc.clone(), format!("{}/exclusiveMaximum", schema_loc), true);
                                    children.push(child);
                                }
                            }
                        }
                    } else {
                        let child = OutputNode::new(format!("{}/exclusiveMaximum", eval_path), instance_loc.clone(), format!("{}/exclusiveMaximum", schema_loc), true);
                        children.push(child);
                    }
                }
                Value::Number(n) => {
                    if let Some(n_f) = n.as_f64() {
                        if instance_num >= n_f {
                            valid = false;
                            let instance_str = serde_json::to_string(instance).unwrap();
                            let msg = format!("{} is greater than or equal to the maximum of {}", instance_str, n);
                            let mut child = OutputNode::new(format!("{}/exclusiveMaximum", eval_path), instance_loc.clone(), format!("{}/exclusiveMaximum", schema_loc), false);
                            let mut m = HashMap::new();
                            m.insert("exclusiveMaximum".to_string(), msg);
                            child.errors = Some(m);
                            children.push(child);
                        } else {
                            let child = OutputNode::new(format!("{}/exclusiveMaximum", eval_path), instance_loc.clone(), format!("{}/exclusiveMaximum", schema_loc), true);
                            children.push(child);
                        }
                    }
                }
                _ => {}
            }
        }
        if let Some(multiple) = obj.get("multipleOf") {
            if let Some(mult_f) = multiple.as_f64() {
                if mult_f != 0.0 {
                    let rem = instance_num / mult_f;
                    // Check if rem is integer within epsilon
                    let is_multiple = (rem.fract().abs() < 1e-9) || ((rem - rem.round()).abs() < 1e-9);
                    if !is_multiple {
                        // Use tolerance for floating
                        let diff = (instance_num - (rem.round() * mult_f)).abs();
                        if diff > 1e-9 {
                            valid = false;
                            let instance_str = serde_json::to_string(instance).unwrap();
                            let msg = format!("{} is not a multiple of {}", instance_str, multiple);
                            let mut child = OutputNode::new(format!("{}/multipleOf", eval_path), instance_loc.clone(), format!("{}/multipleOf", schema_loc), false);
                            let mut m = HashMap::new();
                            m.insert("multipleOf".to_string(), msg);
                            child.errors = Some(m);
                            children.push(child);
                        } else {
                            let child = OutputNode::new(format!("{}/multipleOf", eval_path), instance_loc.clone(), format!("{}/multipleOf", schema_loc), true);
                            children.push(child);
                        }
                    } else {
                        let child = OutputNode::new(format!("{}/multipleOf", eval_path), instance_loc.clone(), format!("{}/multipleOf", schema_loc), true);
                        children.push(child);
                    }
                }
            }
        }
    }

    node.valid = valid;
    node.details = children;
    // For hierarchical, we already have details tree. For list, we will flatten later.
    node
}

fn collect_errors(node: &OutputNode, errors: &mut Vec<String>) {
    if let Some(map) = &node.errors {
        for (_, msg) in map {
            errors.push(msg.clone());
        }
    }
    // For allOf/anyOf etc., we want to avoid collecting children's errors if parent already has error and is anyOf/oneOf/not?
    // Determine if this node is anyOf/oneOf/not/contains etc. where parent error is generic and children also have errors – we should not collect children's.
    let is_generic = node.evaluation_path.ends_with("/anyOf") || node.evaluation_path.ends_with("/oneOf") || node.evaluation_path.ends_with("/not") || node.evaluation_path.ends_with("/contains");
    if is_generic && node.errors.is_some() {
        // don't descend
        return;
    }
    for child in &node.details {
        collect_errors(child, errors);
    }
}

fn flatten_details(node: &OutputNode, list: &mut Vec<Value>) {
    // For list output, we need to produce flat array of all nodes in pre-order.
    // We'll create JSON object for this node (excluding details) and then recurse.
    let mut obj = json!({
        "evaluationPath": node.evaluation_path,
        "instanceLocation": node.instance_location,
        "schemaLocation": node.schema_location,
        "valid": node.valid
    });
    if let Some(err) = &node.errors {
        obj["errors"] = json!(err);
    }
    if let Some(ann) = &node.annotations {
        obj["annotations"] = ann.clone();
    }
    if let Some(dann) = &node.dropped_annotations {
        obj["droppedAnnotations"] = dann.clone();
    }
    list.push(obj);
    for child in &node.details {
        flatten_details(child, list);
        // For children that have their own details, we need to also flatten their children recursively?
        // But our flatten_details already does recursion, so we will include all.
        // However we need to avoid double counting: the child's details are already flattened via recursion.
        // So we just call flatten_details for each child (which will push child and its descendants).
        // But we need to ensure we don't duplicate: the above push for node, then for each child we push child and its descendants.
    }
}

fn node_to_hierarchical_value(node: &OutputNode) -> Value {
    let mut obj = json!({
        "evaluationPath": node.evaluation_path,
        "instanceLocation": node.instance_location,
        "schemaLocation": node.schema_location,
        "valid": node.valid
    });
    if let Some(err) = &node.errors {
        obj["errors"] = json!(err);
    }
    if let Some(ann) = &node.annotations {
        obj["annotations"] = ann.clone();
    }
    if let Some(dann) = &node.dropped_annotations {
        obj["droppedAnnotations"] = dann.clone();
    }
    if !node.details.is_empty() {
        let details: Vec<Value> = node.details.iter().map(|c| node_to_hierarchical_value(c)).collect();
        obj["details"] = Value::Array(details);
    }
    obj
}

fn determine_draft(schema: &Value, forced: Option<Draft>) -> Draft {
    if let Some(d) = forced {
        return d;
    }
    if let Value::Object(map) = schema {
        if let Some(Value::String(s)) = map.get("$schema") {
            if s.contains("draft-04") {
                return Draft::V4;
            } else if s.contains("draft-06") {
                return Draft::V6;
            } else if s.contains("draft-07") {
                return Draft::V7;
            } else if s.contains("2019-09") {
                return Draft::V2019;
            } else if s.contains("2020-12") {
                return Draft::V2020;
            }
        }
    }
    Draft::V2020
}

fn print_help_and_exit() {
    let help = r#"Usage: executable [OPTIONS] [SCHEMA]

Arguments:
  [SCHEMA]  The JSON Schema to validate with (i.e. schema.json)

Options:
  -i, --instance <INSTANCES>       A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)
  -d, --draft <DRAFT>              Enforce a specific JSON Schema draft [possible values: 4, 6, 7, 2019, 2020]
      --assert-format              Turn ON format validation
      --no-assert-format           Turn OFF format validation
      --output <OUTPUT>            Select output style: text (default), flag, list, hierarchical [default: text] [possible values: text, flag, list, hierarchical]
  -v, --version                    Show program's version number and exit
      --errors-only                Only show validation errors
      --connect-timeout <SECONDS>  Timeout for establishing connections (in seconds)
      --timeout <SECONDS>          Total timeout for HTTP requests (in seconds)
  -k, --insecure                   Skip TLS certificate verification (dangerous!)
      --cacert <FILE>              Path to a custom CA certificate file (PEM format)
  -h, --help                       Print help
"#;
    print!("{}", help);
    process::exit(0);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    // Check for help before clap to ensure exact output
    for a in &args[1..] {
        if a == "--help" || a == "-h" {
            print_help_and_exit();
        }
    }
    // Check version before help? Original gave help when both --version and --help present, help wins.
    // So help check first, then version.
    let mut has_version = false;
    for a in &args[1..] {
        if a == "--version" || a == "-v" {
            has_version = true;
            break;
        }
    }
    // If has_version and not has_help (already exited), handle version via clap? We'll let clap handle but also manual
    // Use clap for parsing
    let mut cmd = Command::new("executable")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("schema").help("The JSON Schema to validate with (i.e. schema.json)").value_name("SCHEMA"))
        .arg(Arg::new("instance").short('i').long("instance").value_name("INSTANCES").num_args(1).action(clap::ArgAction::Append).help("A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)"))
        .arg(Arg::new("draft").short('d').long("draft").value_name("DRAFT").value_parser(["4","6","7","2019","2020"]).help("Enforce a specific JSON Schema draft [possible values: 4, 6, 7, 2019, 2020]"))
        .arg(Arg::new("assert-format").long("assert-format").action(clap::ArgAction::SetTrue).help("Turn ON format validation"))
        .arg(Arg::new("no-assert-format").long("no-assert-format").action(clap::ArgAction::SetTrue).help("Turn OFF format validation"))
        .arg(Arg::new("output").long("output").value_name("OUTPUT").default_value("text").value_parser(["text","flag","list","hierarchical"]).help("Select output style: text (default), flag, list, hierarchical"))
        .arg(Arg::new("version").short('v').long("version").action(clap::ArgAction::SetTrue).help("Show program's version number and exit"))
        .arg(Arg::new("errors-only").long("errors-only").action(clap::ArgAction::SetTrue).help("Only show validation errors"))
        .arg(Arg::new("connect-timeout").long("connect-timeout").value_name("SECONDS").value_parser(clap::value_parser!(f64)).help("Timeout for establishing connections (in seconds)"))
        .arg(Arg::new("timeout").long("timeout").value_name("SECONDS").value_parser(clap::value_parser!(f64)).help("Total timeout for HTTP requests (in seconds)"))
        .arg(Arg::new("insecure").short('k').long("insecure").action(clap::ArgAction::SetTrue).help("Skip TLS certificate verification (dangerous!)"))
        .arg(Arg::new("cacert").long("cacert").value_name("FILE").help("Path to a custom CA certificate file (PEM format)"))
        .arg(Arg::new("help").short('h').long("help").action(clap::ArgAction::SetTrue).help("Print help"));

    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            e.exit();
        }
    };

    if matches.get_flag("help") {
        print_help_and_exit();
    }
    if matches.get_flag("version") {
        println!("Version: 0.41.0");
        process::exit(0);
    }

    let schema_path = match matches.get_one::<String>("schema") {
        Some(p) => p.clone(),
        None => {
            let err = cmd.error(clap::error::ErrorKind::MissingRequiredArgument, "the following required arguments were not provided:\n  <SCHEMA>");
            err.exit();
        }
    };

    // Handle cacert before other processing
    if let Some(cacert_path) = matches.get_one::<String>("cacert") {
        // Check file existence
        match fs::read_to_string(cacert_path) {
            Ok(content) => {
                // Check if contains BEGIN CERTIFICATE
                if content.contains("-----BEGIN CERTIFICATE-----") {
                    // Try to extract base64 between header and footer
                    let mut in_cert = false;
                    let mut b64 = String::new();
                    for line in content.lines() {
                        if line.contains("-----BEGIN CERTIFICATE-----") {
                            in_cert = true;
                            continue;
                        }
                        if line.contains("-----END CERTIFICATE-----") {
                            in_cert = false;
                            break;
                        }
                        if in_cert {
                            b64.push_str(line.trim());
                        }
                    }
                    // Try base64 decode
                    let decoded = base64::Engine::decode(&base64::engine::general_purpose::STANDARD, &b64);
                    let is_valid_cert = if let Ok(bytes) = decoded {
                        // Check starts with 0x30 0x82 and length > 100
                        bytes.len() > 100 && bytes[0] == 0x30 && bytes[1] == 0x82
                    } else {
                        false
                    };
                    if !is_valid_cert {
                        // Also check empty base64? Already false
                        println!("Error: Failed to build HTTP client: builder error");
                        process::exit(1);
                    }
                    // otherwise valid, continue
                } else {
                    // No cert header, treat as valid (empty or invalid pem without header)
                    // Do nothing
                }
            }
            Err(e) => {
                println!("Error: Failed to read certificate file '{}': {}", cacert_path, e);
                process::exit(1);
            }
        }
    }

    // Determine output style
    let output_style = matches.get_one::<String>("output").unwrap().clone();

    let errors_only = matches.get_flag("errors-only");

    // Determine draft
    let forced_draft = matches.get_one::<String>("draft").and_then(|s| Draft::from_str(s));
    // Determine assert_format: last wins
    let mut assert_format = false; // default false
    // Scan args for order
    let mut last_assert: Option<bool> = None;
    for a in &args {
        if a == "--assert-format" {
            last_assert = Some(true);
        } else if a == "--no-assert-format" {
            last_assert = Some(false);
        }
    }
    if let Some(v) = last_assert {
        assert_format = v;
    }

    // Read schema file
    let schema_content = match fs::read_to_string(&schema_path) {
        Ok(c) => c,
        Err(e) => {
            println!("Error: {}", e);
            process::exit(1);
        }
    };
    let schema_json: Value = match serde_json::from_str(&schema_content) {
        Ok(v) => v,
        Err(e) => {
            println!("Error: {}", e);
            process::exit(1);
        }
    };

    let draft = determine_draft(&schema_json, forced_draft);
    // Validate schema meta
    let schema_meta_valid = validate_schema_meta(&schema_json, draft);
    let schema_base_uri = {
        let p = Path::new(&schema_path);
        let abs = if p.is_absolute() {
            p.to_path_buf()
        } else {
            env::current_dir().unwrap_or_else(|_| PathBuf::from(".")).join(p)
        };
        // canonicalize if possible
        let canon = fs::canonicalize(&abs).unwrap_or(abs);
        format!("file://{}", canon.display())
    };
    let base_path = Path::new(&schema_path).parent().unwrap_or_else(|| Path::new(".")).to_path_buf();

    let instances: Vec<String> = if let Some(vals) = matches.get_many::<String>("instance") {
        vals.cloned().collect()
    } else {
        vec![]
    };

    // If no instances, handle schema validation only
    if instances.is_empty() {
        match schema_meta_valid {
            Ok(()) => {
                // Schema valid
                if errors_only {
                    // For valid schema with errors-only, print nothing
                    process::exit(0);
                }
                match output_style.as_str() {
                    "text" => {
                        println!("Schema is valid");
                        process::exit(0);
                    }
                    "flag" => {
                        let out = json!({
                            "output": "flag",
                            "payload": {"valid": true},
                            "schema": schema_path
                        });
                        println!("{}", serde_json::to_string(&out).unwrap());
                        process::exit(0);
                    }
                    "list" => {
                        // For valid schema, produce payload with valid true and details?
                        // Simplified: produce valid true with empty details or minimal
                        // To mimic original's huge output, we could produce a simple one, but we will produce a minimal valid list
                        // For now, produce payload with valid true and details containing meta-schema valid?
                        // We'll produce a simple payload with valid true and details with one entry for root
                        let payload = json!({
                            "valid": true,
                            "details": [
                                {"evaluationPath": "", "instanceLocation": "", "schemaLocation": "https://json-schema.org/draft/2020-12/schema#", "valid": true}
                            ]
                        });
                        let out = json!({
                            "output": "list",
                            "payload": payload,
                            "schema": schema_path
                        });
                        println!("{}", serde_json::to_string(&out).unwrap());
                        process::exit(0);
                    }
                    "hierarchical" => {
                        let payload = json!({
                            "valid": true,
                            "evaluationPath": "",
                            "instanceLocation": "",
                            "schemaLocation": "https://json-schema.org/draft/2020-12/schema#",
                            "details": []
                        });
                        let out = json!({
                            "output": "hierarchical",
                            "payload": payload,
                            "schema": schema_path
                        });
                        println!("{}", serde_json::to_string(&out).unwrap());
                        process::exit(0);
                    }
                    _ => unreachable!(),
                }
            }
            Err(msg) => {
                // Schema invalid
                match output_style.as_str() {
                    "text" => {
                        println!("Schema is invalid. Error: {}", msg);
                        process::exit(1);
                    }
                    "flag" => {
                        let out = json!({
                            "output": "flag",
                            "payload": {"valid": false},
                            "schema": schema_path
                        });
                        println!("{}", serde_json::to_string(&out).unwrap());
                        process::exit(1);
                    }
                    "list" => {
                        // Produce list with valid false
                        let payload = json!({
                            "valid": false,
                            "details": [
                                {"evaluationPath": "", "instanceLocation": "", "schemaLocation": "https://json-schema.org/draft/2020-12/schema#", "valid": false, "errors": {"anyOf": msg}}
                            ]
                        });
                        let out = json!({
                            "output": "list",
                            "payload": payload,
                            "schema": schema_path
                        });
                        println!("{}", serde_json::to_string(&out).unwrap());
                        process::exit(1);
                    }
                    "hierarchical" => {
                        let payload = json!({
                            "valid": false,
                            "evaluationPath": "",
                            "instanceLocation": "",
                            "schemaLocation": "https://json-schema.org/draft/2020-12/schema#",
                            "details": [
                                {"evaluationPath": "/type", "instanceLocation": "", "schemaLocation": "https://json-schema.org/draft/2020-12/schema#/type", "valid": false, "errors": {"anyOf": msg}}
                            ]
                        });
                        let out = json!({
                            "output": "hierarchical",
                            "payload": payload,
                            "schema": schema_path
                        });
                        println!("{}", serde_json::to_string(&out).unwrap());
                        process::exit(1);
                    }
                    _ => unreachable!(),
                }
            }
        }
    }

    // Instances provided: need to validate each
    // First, if schema is invalid, handle as schema invalid (takes precedence)
    if let Err(msg) = schema_meta_valid {
        // Schema invalid with instances: original printed "Schema is invalid. Error: ..." to stdout and exit 1, regardless of output style? For flag/list it gave flag with valid false, not text. Let's see earlier: with invalid schema and instance provided, flag output gave flag JSON, not text. So for schema invalid with instances, behavior depends on output style similarly.
        // For text with instance, it still gave "Schema is invalid. Error: ..."
        match output_style.as_str() {
            "text" => {
                println!("Schema is invalid. Error: {}", msg);
                process::exit(1);
            }
            "flag" | "list" | "hierarchical" => {
                // For these, produce same as schema-only invalid but without instance field? Actually earlier with invalid schema and instance, flag output gave {"output":"flag","payload":{"valid":false},"schema":"..."} – no instance field! Let's check: earlier we tested invalid schema with instance and flag gave same as schema alone? We saw: `invalid schema with instance flag: {"output":"flag","payload":{"valid":false},"schema":"/tmp/...}` – indeed no instance field. So for schema invalid, instance is ignored.
                match output_style.as_str() {
                    "flag" => {
                        let out = json!({
                            "output": "flag",
                            "payload": {"valid": false},
                            "schema": schema_path
                        });
                        println!("{}", serde_json::to_string(&out).unwrap());
                        process::exit(1);
                    }
                    "list" => {
                        let payload = json!({"valid": false, "details": [{"valid": false, "evaluationPath": "", "instanceLocation": "", "schemaLocation": "https://json-schema.org/draft/2020-12/schema#", "errors": {"anyOf": msg}}]});
                        let out = json!({"output":"list","payload": payload, "schema": schema_path});
                        println!("{}", serde_json::to_string(&out).unwrap());
                        process::exit(1);
                    }
                    "hierarchical" => {
                        let payload = json!({"valid": false, "evaluationPath": "", "instanceLocation": "", "schemaLocation": "https://json-schema.org/draft/2020-12/schema#", "details": []});
                        let out = json!({"output":"hierarchical","payload": payload, "schema": schema_path});
                        println!("{}", serde_json::to_string(&out).unwrap());
                        process::exit(1);
                    }
                    _ => unreachable!(),
                }
            }
            _ => unreachable!(),
        }
    }

    // Schema valid, proceed to validate each instance
    let ctx = Context {
        draft,
        assert_format,
        base_path: base_path.clone(),
        schema_path_str: schema_path.clone(),
        schema_base_uri: schema_base_uri.clone(),
    };

    let mut overall_valid = true;
    let mut outputs: Vec<String> = Vec::new();
    let mut text_outputs: Vec<String> = Vec::new();

    for inst_path in &instances {
        // Read instance file
        let inst_content = match fs::read_to_string(inst_path) {
            Ok(c) => c,
            Err(e) => {
                println!("Error: {}", e);
                process::exit(1);
            }
        };
        let inst_json: Value = match serde_json::from_str(&inst_content) {
            Ok(v) => v,
            Err(e) => {
                println!("Error: {}", e);
                process::exit(1);
            }
        };
        let root_node = validate(&schema_json, &inst_json, "".to_string(), "".to_string(), schema_base_uri.clone(), &ctx, &schema_json, &base_path);
        let is_valid = root_node.valid;
        if !is_valid {
            overall_valid = false;
        }
        // Collect errors for text
        let mut errors: Vec<String> = Vec::new();
        collect_errors(&root_node, &mut errors);
        match output_style.as_str() {
            "text" => {
                if errors_only && is_valid {
                    // skip
                } else if is_valid {
                    text_outputs.push(format!("{} - VALID", inst_path));
                } else {
                    let mut s = format!("{} - INVALID. Errors:", inst_path);
                    for (i, e) in errors.iter().enumerate() {
                        s.push_str(&format!("\n{}. {}", i+1, e));
                    }
                    text_outputs.push(s);
                }
            }
            "flag" => {
                if errors_only && is_valid {
                    // skip
                } else {
                    let out = json!({
                        "instance": inst_path,
                        "output": "flag",
                        "payload": {"valid": is_valid},
                        "schema": schema_path
                    });
                    outputs.push(serde_json::to_string(&out).unwrap());
                }
            }
            "list" => {
                if errors_only && is_valid {
                    // skip
                } else {
                    // Build flat details
                    let mut flat: Vec<Value> = Vec::new();
                    // For list, we need to flatten root and its children
                    // Our root_node already contains children, but we need to include root itself and then all descendants
                    // We'll create a helper that flattens
                    // For valid case, we need to include root and its type etc. Our root_node's details are children at top level.
                    // Flatten will include root and all descendants
                    flatten_details(&root_node, &mut flat);
                    let payload = json!({
                        "valid": is_valid,
                        "details": flat
                    });
                    let out = json!({
                        "instance": inst_path,
                        "output": "list",
                        "payload": payload,
                        "schema": schema_path
                    });
                    outputs.push(serde_json::to_string(&out).unwrap());
                }
            }
            "hierarchical" => {
                if errors_only && is_valid {
                    // skip
                } else {
                    let payload = node_to_hierarchical_value(&root_node);
                    let out = json!({
                        "instance": inst_path,
                        "output": "hierarchical",
                        "payload": payload,
                        "schema": schema_path
                    });
                    outputs.push(serde_json::to_string(&out).unwrap());
                }
            }
            _ => unreachable!(),
        }
    }

    match output_style.as_str() {
        "text" => {
            for line in text_outputs {
                println!("{}", line);
            }
        }
        _ => {
            for line in outputs {
                println!("{}", line);
            }
        }
    }

    if overall_valid {
        process::exit(0);
    } else {
        process::exit(1);
    }
}
RS
"}

actions.command:
cat > src/main.rs <<'RS'
use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

use clap::{Arg, Command};
use regex::Regex;
use serde_json::{json, Value};
use url::Url;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Draft {
    V4,
    V6,
    V7,
    V2019,
    V2020,
}

impl Draft {
    fn from_str(s: &str) -> Option<Self> {
        match s {
            "4" => Some(Draft::V4),
            "6" => Some(Draft::V6),
            "7" => Some(Draft::V7),
            "2019" => Some(Draft::V2019),
            "2020" => Some(Draft::V2020),
            _ => None,
        }
    }
}

#[derive(Clone, Debug)]
struct Context {
    draft: Draft,
    assert_format: bool,
    base_path: PathBuf,
    schema_path_str: String,
    schema_base_uri: String,
}

#[derive(Clone, Debug)]
struct OutputNode {
    evaluation_path: String,
    instance_location: String,
    schema_location: String,
    valid: bool,
    errors: Option<HashMap<String, String>>,
    annotations: Option<Value>,
    dropped_annotations: Option<Value>,
    details: Vec<OutputNode>,
}

impl OutputNode {
    fn new(evaluation_path: String, instance_location: String, schema_location: String, valid: bool) -> Self {
        OutputNode {
            evaluation_path,
            instance_location,
            schema_location,
            valid,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Vec::new(),
        }
    }
}

fn escape_pointer(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

fn unescape_pointer(s: &str) -> String {
    s.replace("~1", "/").replace("~0", "~")
}

fn json_pointer_get<'a>(value: &'a Value, pointer: &str) -> Option<&'a Value> {
    if pointer.is_empty() {
        return Some(value);
    }
    if !pointer.starts_with('/') {
        return None;
    }
    let mut cur = value;
    for token in pointer[1..].split('/') {
        let token = unescape_pointer(token);
        match cur {
            Value::Object(map) => cur = map.get(&token)?,
            Value::Array(arr) => {
                let idx: usize = token.parse().ok()?;
                cur = arr.get(idx)?;
            }
            _ => return None,
        }
    }
    Some(cur)
}

fn format_enum_list(parts: &[String]) -> String {
    if parts.len() == 1 {
        parts[0].clone()
    } else if parts.len() == 2 {
        format!("{} or {}", parts[0], parts[1])
    } else {
        let mut s = String::new();
        for (i, p) in parts.iter().enumerate() {
            if i == parts.len() - 1 {
                s.push_str("or ");
                s.push_str(p);
            } else {
                s.push_str(p);
                s.push_str(", ");
            }
        }
        s
    }
}

fn is_integer(value: &Value) -> bool {
    match value {
        Value::Number(n) => {
            if n.is_i64() || n.is_u64() {
                true
            } else if let Some(f) = n.as_f64() {
                f.fract() == 0.0 && f.is_finite()
            } else {
                false
            }
        }
        _ => false,
    }
}

fn instance_type_str(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Object(_) => "object",
        Value::Array(_) => "array",
        Value::Number(n) => {
            if is_integer(value) {
                "integer"
            } else {
                "number"
            }
        }
        Value::String(_) => "string",
    }
}

fn check_type(expected: &Value, instance: &Value) -> (bool, String) {
    let instance_str = serde_json::to_string(instance).unwrap();
    match expected {
        Value::String(s) => {
            let ok = match s.as_str() {
                "null" => instance.is_null(),
                "boolean" => instance.is_boolean(),
                "object" => instance.is_object(),
                "array" => instance.is_array(),
                "number" => instance.is_number(),
                "string" => instance.is_string(),
                "integer" => is_integer(instance),
                _ => false,
            };
            if ok {
                (true, String::new())
            } else {
                (false, format!("{} is not of type \"{}\"", instance_str, s))
            }
        }
        Value::Array(arr) => {
            // Check if instance matches any type
            let mut allowed: Vec<String> = Vec::new();
            for v in arr {
                if let Value::String(s) = v {
                    allowed.push(s.clone());
                    let ok = match s.as_str() {
                        "null" => instance.is_null(),
                        "boolean" => instance.is_boolean(),
                        "object" => instance.is_object(),
                        "array" => instance.is_array(),
                        "number" => instance.is_number(),
                        "string" => instance.is_string(),
                        "integer" => is_integer(instance),
                        _ => false,
                    };
                    if ok {
                        return (true, String::new());
                    }
                }
            }
            // Not matched
            // Sort allowed alphabetically to match observed behavior? Original sorted integer before string.
            let mut sorted = allowed.clone();
            sorted.sort();
            // Format list as (a, b, c) ?
            // For single type, we already handled, but for array we need plural
            // Observed: 3.14 is not of types (integer, string) – sorted
            let list = sorted.join(", ");
            // Need parentheses and maybe "types"
            // For array with one element? Not needed.
            (false, format!("{} is not of types ({})", instance_str, list))
            // But for original with string/integer, it was "(integer, string)" – sorted
        }
        _ => (false, format!("{} is not of type \"{}\"", instance_str, expected)),
    }
}

fn validate_schema_meta(schema: &Value, draft: Draft) -> Result<(), String> {
    // Minimal meta validation
    // Check type keyword
    if let Value::Object(map) = schema {
        if let Some(type_val) = map.get("type") {
            match type_val {
                Value::String(s) => {
                    let allowed = ["null","boolean","object","array","number","string","integer"];
                    if !allowed.contains(&s.as_str()) {
                        return Err(format!("\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword", s));
                    }
                }
                Value::Array(arr) => {
                    for item in arr {
                        if let Value::String(s) = item {
                            let allowed = ["null","boolean","object","array","number","string","integer"];
                            if !allowed.contains(&s.as_str()) {
                                return Err(format!("\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword", s));
                            }
                        } else {
                            return Err(format!("{} is not of type \"string\"", serde_json::to_string(item).unwrap()));
                        }
                    }
                }
                _ => {
                    // type should be string or array
                    return Err(format!("{} is not of type \"string\"", serde_json::to_string(type_val).unwrap()));
                }
            }
        }
        // Check exclusiveMinimum / exclusiveMaximum based on draft
        if draft == Draft::V2020 || draft == Draft::V2019 || draft == Draft::V7 || draft == Draft::V6 {
            if let Some(em) = map.get("exclusiveMinimum") {
                if !em.is_number() {
                    return Err(format!("{} is not of type \"number\"", serde_json::to_string(em).unwrap()));
                }
            }
            if let Some(em) = map.get("exclusiveMaximum") {
                if !em.is_number() {
                    return Err(format!("{} is not of type \"number\"", serde_json::to_string(em).unwrap()));
                }
            }
        } else if draft == Draft::V4 {
            if let Some(em) = map.get("exclusiveMinimum") {
                if !em.is_boolean() {
                    // In draft 4, exclusiveMinimum should be boolean, but if it's number maybe invalid?
                    // We'll allow number? But spec says boolean. For simplicity, if it's not boolean, error.
                    // However we previously supported both for instance validation, but for schema validation we strict.
                    // Check if it's boolean else error
                    if !em.is_boolean() && !em.is_number() {
                        return Err(format!("{} is not of type \"boolean\"", serde_json::to_string(em).unwrap()));
                    }
                }
            }
            if let Some(em) = map.get("exclusiveMaximum") {
                if !em.is_boolean() {
                    if !em.is_boolean() && !em.is_number() {
                        return Err(format!("{} is not of type \"boolean\"", serde_json::to_string(em).unwrap()));
                    }
                }
            }
        }
        // Check properties should be object
        // etc. Minimal
    } else if schema.is_boolean() {
        // boolean schemas are always valid
        return Ok(());
    } else if schema.is_array() {
        // schema as array is not valid? But json schema can be false? Actually schema can be boolean or object only. Array not valid.
        // But we treat as invalid?
        // For simplicity, consider not object/boolean invalid?
        // Original's invalid schema with type invalid_type is object, so not needed.
    }
    Ok(())
}

fn resolve_ref(ref_str: &str, base_path: &Path, root: &Value) -> Option<Value> {
    // Handle internal refs
    if ref_str.starts_with('#') {
        let pointer = &ref_str[1..]; // includes leading / or empty
        if let Some(v) = json_pointer_get(root, pointer) {
            return Some(v.clone());
        } else {
            return None;
        }
    }
    // Handle file refs with possible fragment
    let parts: Vec<&str> = ref_str.splitn(2, '#').collect();
    let file_part = parts[0];
    let pointer = if parts.len() > 1 { parts[1] } else { "" };
    // Resolve file path relative to base_path
    let target_path = base_path.join(file_part);
    // Try to read file
    // If file_part is URL (http/https), ignore for offline, return None
    if file_part.starts_with("http://") || file_part.starts_with("https://") {
        // For offline, we can't fetch, try to treat as not found
        return None;
    }
    let content = fs::read_to_string(&target_path).ok()?;
    let json: Value = serde_json::from_str(&content).ok()?;
    if pointer.is_empty() {
        Some(json)
    } else {
        json_pointer_get(&json, pointer).cloned()
    }
}

fn validate_format(format: &str, instance_str: &str) -> bool {
    match format {
        "email" => {
            // simple email regex as observed
            // Must contain @ and .
            // Original used something like ^[^@]+@[^@]+\.[^@]+$
            let re = Regex::new(r"^[^@]+@[^@]+\.[^@]+$").unwrap();
            re.is_match(instance_str)
        }
        "hostname" => {
            let re = Regex::new(r"^[a-zA-Z0-9][a-zA-Z0-9\-\.]*[a-zA-Z0-9]$").unwrap();
            re.is_match(instance_str)
        }
        "ipv4" => {
            let parts: Vec<&str> = instance_str.split('.').collect();
            if parts.len() != 4 { return false; }
            for p in parts {
                if let Ok(n) = p.parse::<u8>() {
                    // also need to ensure no leading zeros? Keep simple
                } else {
                    return false;
                }
            }
            true
        }
        "ipv6" => {
            // Use std net parse
            instance_str.parse::<std::net::Ipv6Addr>().is_ok()
        }
        "uri" => {
            Url::parse(instance_str).is_ok()
        }
        "uri-reference" => {
            Url::parse(instance_str).is_ok() || instance_str.starts_with('/') || instance_str.starts_with('#')
        }
        "date-time" => {
            // Try chrono
            chrono::DateTime::parse_from_rfc3339(instance_str).is_ok()
        }
        "date" => {
            chrono::NaiveDate::parse_from_str(instance_str, "%Y-%m-%d").is_ok()
        }
        "time" => {
            chrono::NaiveTime::parse_from_str(instance_str, "%H:%M:%S").is_ok()
        }
        "uuid" => {
            // Simple uuid regex
            let re = Regex::new(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$").unwrap();
            re.is_match(instance_str)
        }
        "regex" => {
            Regex::new(instance_str).is_ok()
        }
        "json-pointer" => {
            instance_str.is_empty() || instance_str.starts_with('/')
        }
        _ => true, // unknown formats are valid
    }
}

fn validate(schema: &Value, instance: &Value, instance_loc: String, eval_path: String, schema_loc: String, ctx: &Context, root_schema: &Value, base_path: &Path) -> OutputNode {
    // Handle boolean schema
    if let Value::Bool(b) = schema {
        if *b {
            return OutputNode::new(eval_path, instance_loc, schema_loc, true);
        } else {
            let instance_str = serde_json::to_string(instance).unwrap();
            let msg = format!("False schema does not allow {}", instance_str);
            let mut node = OutputNode::new(eval_path, instance_loc, schema_loc, false);
            let mut map = HashMap::new();
            map.insert("falseSchema".to_string(), msg);
            node.errors = Some(map);
            return node;
        }
    }
    // Ensure schema is object
    let obj = match schema.as_object() {
        Some(o) => o,
        None => {
            // If schema is not object nor bool, treat as valid? But schema should be object.
            return OutputNode::new(eval_path, instance_loc, schema_loc, true);
        }
    };

    let mut node = OutputNode::new(eval_path.clone(), instance_loc.clone(), schema_loc.clone(), true);
    let mut children: Vec<OutputNode> = Vec::new();
    let mut valid = true;

    // Handle $ref
    if let Some(ref_val) = obj.get("$ref") {
        if let Value::String(ref_str) = ref_val {
            if let Some(resolved) = resolve_ref(ref_str, base_path, root_schema) {
                // Validate against resolved
                let child_eval = format!("{}/$ref", eval_path);
                let child_schema_loc = format!("{}/$ref", schema_loc);
                let child = validate(&resolved, instance, instance_loc.clone(), child_eval, child_schema_loc, ctx, root_schema, base_path);
                if !child.valid {
                    valid = false;
                }
                children.push(child);
                // In JSON Schema, $ref may be alongside other keywords, but we will also process other keywords after.
            } else {
                // Failed to resolve, treat as valid? Or invalid with error?
                // For offline, if ref is remote and cannot fetch, we could consider valid? But original would try to fetch and maybe fail with timeout? For now treat as valid.
            }
        }
    }

    // type
    if let Some(type_val) = obj.get("type") {
        let (is_valid, err_msg) = check_type(type_val, instance);
        let child = {
            let mut n = OutputNode::new(format!("{}/type", eval_path), instance_loc.clone(), format!("{}/type", schema_loc), is_valid);
            if !is_valid {
                let mut m = HashMap::new();
                m.insert("type".to_string(), err_msg);
                n.errors = Some(m);
                valid = false;
            }
            n
        };
        children.push(child);
    }

    // enum
    if let Some(enum_val) = obj.get("enum") {
        if let Value::Array(arr) = enum_val {
            let contains = arr.contains(instance);
            let child_valid = contains;
            if !child_valid {
                valid = false;
            }
            let mut child = OutputNode::new(format!("{}/enum", eval_path), instance_loc.clone(), format!("{}/enum", schema_loc), child_valid);
            if !child_valid {
                let instance_str = serde_json::to_string(instance).unwrap();
                let parts: Vec<String> = arr.iter().map(|v| serde_json::to_string(v).unwrap()).collect();
                let list_str = format_enum_list(&parts);
                let msg = format!("{} is not one of {}", instance_str, list_str);
                let mut m = HashMap::new();
                m.insert("enum".to_string(), msg);
                child.errors = Some(m);
            }
            children.push(child);
        }
    }

    // const
    if let Some(const_val) = obj.get("const") {
        let is_valid = const_val == instance;
        if !is_valid {
            valid = false;
        }
        let mut child = OutputNode::new(format!("{}/const", eval_path), instance_loc.clone(), format!("{}/const", schema_loc), is_valid);
        if !is_valid {
            let msg = format!("{} was expected", serde_json::to_string(const_val).unwrap());
            let mut m = HashMap::new();
            m.insert("const".to_string(), msg);
            child.errors = Some(m);
        }
        children.push(child);
    }

    // allOf
    if let Some(all_of) = obj.get("allOf") {
        if let Value::Array(arr) = all_of {
            let mut all_valid = true;
            let mut all_children = Vec::new();
            for (i, sub) in arr.iter().enumerate() {
                let sub_eval = format!("{}/allOf/{}", eval_path, i);
                let sub_loc = format!("{}/allOf/{}", schema_loc, i);
                let child = validate(sub, instance, instance_loc.clone(), sub_eval, sub_loc, ctx, root_schema, base_path);
                if !child.valid {
                    all_valid = false;
                }
                all_children.push(child);
            }
            let mut child = OutputNode::new(format!("{}/allOf", eval_path), instance_loc.clone(), format!("{}/allOf", schema_loc), all_valid);
            child.details = all_children;
            if !all_valid {
                valid = false;
            }
            children.push(child);
        }
    }

    // anyOf
    if let Some(any_of) = obj.get("anyOf") {
        if let Value::Array(arr) = any_of {
            let mut any_valid = false;
            let mut any_children = Vec::new();
            for (i, sub) in arr.iter().enumerate() {
                let sub_eval = format!("{}/anyOf/{}", eval_path, i);
                let sub_loc = format!("{}/anyOf/{}", schema_loc, i);
                let child = validate(sub, instance, instance_loc.clone(), sub_eval, sub_loc, ctx, root_schema, base_path);
                if child.valid {
                    any_valid = true;
                }
                any_children.push(child);
            }
            let mut child = OutputNode::new(format!("{}/anyOf", eval_path), instance_loc.clone(), format!("{}/anyOf", schema_loc), any_valid);
            child.details = any_children;
            if !any_valid {
                valid = false;
                let instance_str = serde_json::to_string(instance).unwrap();
                let msg = format!("{} is not valid under any of the schemas listed in the 'anyOf' keyword", instance_str);
                let mut m = HashMap::new();
                m.insert("anyOf".to_string(), msg);
                child.errors = Some(m);
            }
            children.push(child);
        }
    }

    // oneOf
    if let Some(one_of) = obj.get("oneOf") {
        if let Value::Array(arr) = one_of {
            let mut valid_count = 0;
            let mut one_children = Vec::new();
            for (i, sub) in arr.iter().enumerate() {
                let sub_eval = format!("{}/oneOf/{}", eval_path, i);
                let sub_loc = format!("{}/oneOf/{}", schema_loc, i);
                let child = validate(sub, instance, instance_loc.clone(), sub_eval, sub_loc, ctx, root_schema, base_path);
                if child.valid {
                    valid_count += 1;
                }
                one_children.push(child);
            }
            let is_valid = valid_count == 1;
            let mut child = OutputNode::new(format!("{}/oneOf", eval_path), instance_loc.clone(), format!("{}/oneOf", schema_loc), is_valid);
            child.details = one_children;
            if !is_valid {
                valid = false;
                let instance_str = serde_json::to_string(instance).unwrap();
                let msg = if valid_count == 0 {
                    format!("{} is not valid under any of the schemas listed in the 'oneOf' keyword", instance_str)
                } else {
                    format!("{} is valid under more than one of the schemas listed in the 'oneOf' keyword", instance_str)
                };
                let mut m = HashMap::new();
                m.insert("oneOf".to_string(), msg);
                child.errors = Some(m);
            }
            children.push(child);
        }
    }

    // not
    if let Some(not_schema) = obj.get("not") {
        let sub = validate(not_schema, instance, instance_loc.clone(), format!("{}/not", eval_path), format!("{}/not", schema_loc), ctx, root_schema, base_path);
        let is_valid = !sub.valid;
        let mut child = OutputNode::new(format!("{}/not", eval_path), instance_loc.clone(), format!("{}/not", schema_loc), is_valid);
        // For not, we need to include the sub as detail? In original hierarchical, not had details of the inner type?
        // We'll store sub as detail
        child.details = vec![sub];
        if !is_valid {
            valid = false;
            let instance_str = serde_json::to_string(instance).unwrap();
            let not_str = serde_json::to_string(not_schema).unwrap();
            let msg = format!("{} is not allowed for {}", not_str, instance_str);
            let mut m = HashMap::new();
            m.insert("not".to_string(), msg);
            child.errors = Some(m);
        }
        children.push(child);
    }

    // if/then/else
    if let Some(if_schema) = obj.get("if") {
        let if_node = validate(if_schema, instance, instance_loc.clone(), format!("{}/if", eval_path), format!("{}/if", schema_loc), ctx, root_schema, base_path);
        let condition = if_node.valid;
        if condition {
            if let Some(then_schema) = obj.get("then") {
                let then_node = validate(then_schema, instance, instance_loc.clone(), format!("{}/then", eval_path), format!("{}/then", schema_loc), ctx, root_schema, base_path);
                if !then_node.valid {
                    valid = false;
                }
                let mut child = OutputNode::new(format!("{}/if", eval_path), instance_loc.clone(), format!("{}/if", schema_loc), then_node.valid);
                // In original, if/then/else handling produced evaluationPath for if and then separately? Let's simplify: we push then_node as child of if?
                // We'll push if_node and then_node separately?
                // For simplicity, push if_node (valid true) and then_node
                children.push(if_node);
                let mut then_wrapper = OutputNode::new(format!("{}/then", eval_path), instance_loc.clone(), format!("{}/then", schema_loc), then_node.valid);
                then_wrapper.details = vec![then_node];
                // But then_node's errors will be leaf
                children.push(then_wrapper);
            } else {
                children.push(if_node);
            }
        } else {
            if let Some(else_schema) = obj.get("else") {
                let else_node = validate(else_schema, instance, instance_loc.clone(), format!("{}/else", eval_path), format!("{}/else", schema_loc), ctx, root_schema, base_path);
                if !else_node.valid {
                    valid = false;
                }
                children.push(if_node);
                let mut else_wrapper = OutputNode::new(format!("{}/else", eval_path), instance_loc.clone(), format!("{}/else", schema_loc), else_node.valid);
                else_wrapper.details = vec![else_node];
                children.push(else_wrapper);
            } else {
                children.push(if_node);
            }
        }
    }

    // Object-specific keywords
    if instance.is_object() {
        let map = instance.as_object().unwrap();
        // properties
        if let Some(props) = obj.get("properties") {
            if let Value::Object(prop_map) = props {
                let mut prop_children = Vec::new();
                let mut prop_valid = true;
                let mut annotation_keys = Vec::new();
                let mut dropped = Vec::new();
                for (key, sub_schema) in prop_map {
                    if let Some(val) = map.get(key) {
                        let child_loc = if instance_loc.is_empty() {
                            format!("/{}", escape_pointer(key))
                        } else {
                            format!("{}/{}", instance_loc, escape_pointer(key))
                        };
                        let child_eval = format!("{}/properties/{}", eval_path, escape_pointer(key));
                        let child_schema_loc = format!("{}/properties/{}", schema_loc, escape_pointer(key));
                        let child = validate(sub_schema, val, child_loc, child_eval, child_schema_loc, ctx, root_schema, base_path);
                        if !child.valid {
                            prop_valid = false;
                            valid = false;
                            dropped.push(Value::String(key.clone()));
                        } else {
                            annotation_keys.push(Value::String(key.clone()));
                        }
                        prop_children.push(child);
                    }
                }
                let mut child = OutputNode::new(format!("{}/properties", eval_path), instance_loc.clone(), format!("{}/properties", schema_loc), prop_valid);
                child.details = prop_children;
                if prop_valid {
                    if !annotation_keys.is_empty() {
                        child.annotations = Some(Value::Array(annotation_keys));
                    } else {
                        child.annotations = Some(Value::Array(vec![]));
                    }
                } else {
                    // dropped
                    if !annotation_keys.is_empty() || !dropped.is_empty() {
                        // In observed, valid false had droppedAnnotations
                        child.dropped_annotations = Some(Value::Array(dropped));
                        if !annotation_keys.is_empty() {
                            // Actually for invalid, maybe still have annotations? In example with name 123, they had droppedAnnotations ["name"]
                            // We'll set dropped
                        }
                    } else {
                        child.annotations = Some(Value::Array(vec![]));
                    }
                }
                // For list output, we had also individual property nodes directly? But we already have them as details of properties. However root's details should include properties node, which contains property nodes.
                // For text, leaf errors are inside prop_children, so will be collected.
                children.push(child);
            }
        }
        // required
        if let Some(req) = obj.get("required") {
            if let Value::Array(arr) = req {
                let mut missing = Vec::new();
                for item in arr {
                    if let Value::String(s) = item {
                        if !map.contains_key(s) {
                            missing.push(s.clone());
                        }
                    }
                }
                // Create node for required
                let is_valid = missing.is_empty();
                let mut child = OutputNode::new(format!("{}/required", eval_path), instance_loc.clone(), format!("{}/required", schema_loc), is_valid);
                if !is_valid {
                    valid = false;
                    // For each missing, we could produce separate error? Original had one error per missing? Let's create one error for first missing, but to support multiple missing we need multiple nodes? In list output for required missing single, they had one node with error. For multiple missing, they might have multiple errors? Let's check oneOf case? Not sure.
                    // We'll create one node with error for each missing? But our node can only have one errors map. For multiple missing, text would have multiple lines each for required. How to represent? We could create child.details for each missing? Simpler: For each missing, create a child node under required with its own error, but original's structure for required missing had just one node with error, not multiple children.
                    // For simplicity, if multiple missing, we will produce one node per missing property as separate child under required? But then required node would have details.
                    // Let's instead create one node per missing as separate error entries in text collection: we will create multiple child nodes each with one missing error, and required node will have those as details.
                    // However our current child is the required node itself. To support multiple missing errors, we can create details for each missing.
                    let mut req_children = Vec::new();
                    for miss in &missing {
                        let msg = format!("\"{}\" is a required property", miss);
                        let mut m = HashMap::new();
                        m.insert("required".to_string(), msg);
                        // For required, instanceLocation stays at parent, but evaluationPath is /required, instanceLocation is ""
                        // The error's instanceLocation is "" (parent), not the missing property path.
                        let mut err_node = OutputNode::new(format!("{}/required", eval_path), instance_loc.clone(), format!("{}/required", schema_loc), false);
                        err_node.errors = Some(m);
                        req_children.push(err_node);
                    }
                    // If we have req_children, we can set child.details = req_children and also set child valid false, but child.errors maybe also? In original, the required node itself had error, not children. For simplicity, we will set child.errors for first missing, and for additional missing we will create separate nodes as siblings? Actually required is one keyword, but missing multiple properties should produce multiple errors lines. Text would have multiple lines. How to generate multiple lines from single node? Our text collection collects leaf errors from nodes where errors present. If we have single required node with one error, we would only have one line even if two properties missing. So need to produce multiple error lines.
                    // Approach: For each missing, push a separate node as child of required? Then text collection will collect each child's error. Let's create child node for required with details as per missing.
                    if missing.len() == 1 {
                        let miss = &missing[0];
                        let msg = format!("\"{}\" is a required property", miss);
                        let mut m = HashMap::new();
                        m.insert("required".to_string(), msg);
                        child.errors = Some(m);
                    } else {
                        // multiple missing: create details
                        child.details = req_children;
                        // The required node itself valid false, but errors at detail level
                        // For text, we will collect errors from details
                    }
                }
                children.push(child);
            }
        }
        // additionalProperties
        if let Some(add_props) = obj.get("additionalProperties") {
            // add_props can be bool or schema
            let defined_props: std::collections::HashSet<String> = if let Some(props) = obj.get("properties") {
                if let Value::Object(m) = props {
                    m.keys().cloned().collect()
                } else { std::collections::HashSet::new() }
            } else { std::collections::HashSet::new() };
            let pattern_props: Vec<Regex> = if let Some(pat_props) = obj.get("patternProperties") {
                if let Value::Object(m) = pat_props {
                    m.keys().filter_map(|k| Regex::new(k).ok()).collect()
                } else { vec![] }
            } else { vec![] };
            let mut extra_keys: Vec<String> = Vec::new();
            for key in map.keys() {
                if defined_props.contains(key) {
                    continue;
                }
                let mut matched = false;
                for re in &pattern_props {
                    if re.is_match(key) {
                        matched = true;
                        break;
                    }
                }
                if matched {
                    continue;
                }
                extra_keys.push(key.clone());
            }
            if !extra_keys.is_empty() {
                match add_props {
                    Value::Bool(b) => {
                        if !b {
                            valid = false;
                            for key in extra_keys {
                                let msg = format!("Additional properties are not allowed ('{}' was unexpected)", key);
                                let mut m = HashMap::new();
                                m.insert("additionalProperties".to_string(), msg);
                                let mut err_node = OutputNode::new(format!("{}/additionalProperties", eval_path), instance_loc.clone(), format!("{}/additionalProperties", schema_loc), false);
                                err_node.errors = Some(m);
                                // For additionalProperties with bool false, each extra key is separate error? Original had one error for 'b' unexpected. For multiple extra, would have multiple errors? Possibly one per key. We'll create separate nodes for each.
                                // But our structure: additionalProperties node should have details? Let's just push each as separate child under additionalProperties? Simpler: push each as separate node at top level? Actually schemaLocation for additionalProperties is /additionalProperties, but instanceLocation for extra key is /key ?
                                // In original, instanceLocation for additionalProperties error? Not shown clearly. For our minimal, we will just push one node per extra key as separate child.
                                // Instead of creating one node with multiple errors, create one node per extra key.
                                children.push(err_node);
                            }
                            // Need to avoid double counting valid = false already done
                            // We pushed children, but we also need to not push an extra parent node. So we already handled.
                            continue;
                        }
                    }
                    Value::Object(_) | _ => {
                        // additionalProperties is schema, validate each extra key against it
                        for key in extra_keys {
                            if let Some(val) = map.get(&key) {
                                let child_loc = if instance_loc.is_empty() {
                                    format!("/{}", escape_pointer(&key))
                                } else {
                                    format!("{}/{}", instance_loc, escape_pointer(&key))
                                };
                                let child_eval = format!("{}/additionalProperties", eval_path);
                                let child_schema_loc = format!("{}/additionalProperties", schema_loc);
                                let child = validate(add_props, val, child_loc, child_eval, child_schema_loc, ctx, root_schema, base_path);
                                if !child.valid {
                                    valid = false;
                                }
                                children.push(child);
                            }
                        }
                        continue;
                    }
                }
            } else {
                // No extra, create a valid node for additionalProperties? In original, for valid object with no extra, they had no node for additionalProperties? In example with required and properties, they had no additionalProperties node. So we omit if no extra.
            }
        } else {
            // If additionalProperties not present, but we still need to handle patternProperties? Already handled via extra_keys logic but without additionalProperties check, we still need to validate patternProperties values.
            // We'll handle patternProperties below separately
        }
        // patternProperties
        if let Some(pat_props) = obj.get("patternProperties") {
            if let Value::Object(pat_map) = pat_props {
                let mut pat_valid = true;
                let mut pat_children = Vec::new();
                for (pattern, sub_schema) in pat_map {
                    let re = match Regex::new(pattern) {
                        Ok(r) => r,
                        Err(_) => continue,
                    };
                    for (key, val) in map.iter() {
                        if re.is_match(key) {
                            let child_loc = if instance_loc.is_empty() {
                                format!("/{}", escape_pointer(key))
                            } else {
                                format!("{}/{}", instance_loc, escape_pointer(key))
                            };
                            let child_eval = format!("{}/patternProperties/{}", eval_path, escape_pointer(pattern));
                            let child_schema_loc = format!("{}/patternProperties/{}", schema_loc, escape_pointer(pattern));
                            let child = validate(sub_schema, val, child_loc, child_eval, child_schema_loc, ctx, root_schema, base_path);
                            if !child.valid {
                                pat_valid = false;
                                valid = false;
                            }
                            pat_children.push(child);
                        }
                    }
                }
                if !pat_children.is_empty() {
                    let mut child = OutputNode::new(format!("{}/patternProperties", eval_path), instance_loc.clone(), format!("{}/patternProperties", schema_loc), pat_valid);
                    child.details = pat_children;
                    children.push(child);
                }
            }
        }
        // propertyNames
        if let Some(prop_names_schema) = obj.get("propertyNames") {
            let mut prop_names_valid = true;
            let mut prop_children = Vec::new();
