                        if diff > 1e-9 {
                            valid = false;
                            let instance_str = serde_json::to_string(instance).unwrap();
                            let msg = format!("{} is not a multiple of {}", instance_str, multiple);
                            let mut child = OutputNode::new(format!("{}/multipleOf", eval_path), instance_loc.clone(), format!("{}/multipleOf", schema_loc), false);
                            let mut m = HashMap::new();
                            m.insert("multipleOf".to_string(), msg);
                            child.errors = Some(m);
                            children.push(child);
                        } else {
                            let child = OutputNode::new(format!("{}/multipleOf", eval_path), instance_loc.clone(), format!("{}/multipleOf", schema_loc), true);
                            children.push(child);
                        }
                    } else {
                        let child = OutputNode::new(format!("{}/multipleOf", eval_path), instance_loc.clone(), format!("{}/multipleOf", schema_loc), true);
                        children.push(child);
                    }
                }
            }
        }
    }

    node.valid = valid;
    node.details = children;
    // For hierarchical, we already have details tree. For list, we will flatten later.
    node
}

fn collect_errors(node: &OutputNode, errors: &mut Vec<String>) {
    if let Some(map) = &node.errors {
        for (_, msg) in map {
            errors.push(msg.clone());
        }
    }
    // For allOf/anyOf etc., we want to avoid collecting children's errors if parent already has error and is anyOf/oneOf/not?
    // Determine if this node is anyOf/oneOf/not/contains etc. where parent error is generic and children also have errors – we should not collect children's.
    let is_generic = node.evaluation_path.ends_with("/anyOf") || node.evaluation_path.ends_with("/oneOf") || node.evaluation_path.ends_with("/not") || node.evaluation_path.ends_with("/contains");
    if is_generic && node.errors.is_some() {
        // don't descend
        return;
    }
    for child in &node.details {
        collect_errors(child, errors);
    }
}

fn flatten_details(node: &OutputNode, list: &mut Vec<Value>) {
    // For list output, we need to produce flat array of all nodes in pre-order.
    // We'll create JSON object for this node (excluding details) and then recurse.
    let mut obj = json!({
        "evaluationPath": node.evaluation_path,
        "instanceLocation": node.instance_location,
        "schemaLocation": node.schema_location,
        "valid": node.valid
    });
    if let Some(err) = &node.errors {
        obj["errors"] = json!(err);
    }
    if let Some(ann) = &node.annotations {
        obj["annotations"] = ann.clone();
    }
    if let Some(dann) = &node.dropped_annotations {
        obj["droppedAnnotations"] = dann.clone();
    }
    list.push(obj);
    for child in &node.details {
        flatten_details(child, list);
        // For children that have their own details, we need to also flatten their children recursively?
        // But our flatten_details already does recursion, so we will include all.
        // However we need to avoid double counting: the child's details are already flattened via recursion.
        // So we just call flatten_details for each child (which will push child and its descendants).
        // But we need to ensure we don't duplicate: the above push for node, then for each child we push child and its descendants.
    }
}

fn node_to_hierarchical_value(node: &OutputNode) -> Value {
    let mut obj = json!({
        "evaluationPath": node.evaluation_path,
        "instanceLocation": node.instance_location,
        "schemaLocation": node.schema_location,
        "valid": node.valid
    });
    if let Some(err) = &node.errors {
        obj["errors"] = json!(err);
    }
    if let Some(ann) = &node.annotations {
        obj["annotations"] = ann.clone();
    }
    if let Some(dann) = &node.dropped_annotations {
        obj["droppedAnnotations"] = dann.clone();
    }
    if !node.details.is_empty() {
        let details: Vec<Value> = node.details.iter().map(|c| node_to_hierarchical_value(c)).collect();
        obj["details"] = Value::Array(details);
    }
    obj
}

fn determine_draft(schema: &Value, forced: Option<Draft>) -> Draft {
    if let Some(d) = forced {
        return d;
    }
    if let Value::Object(map) = schema {
        if let Some(Value::String(s)) = map.get("$schema") {
            if s.contains("draft-04") {
                return Draft::V4;
            } else if s.contains("draft-06") {
                return Draft::V6;
            } else if s.contains("draft-07") {
                return Draft::V7;
            } else if s.contains("2019-09") {
                return Draft::V2019;
            } else if s.contains("2020-12") {
                return Draft::V2020;
            }
        }
    }
    Draft::V2020
}

fn print_help_and_exit() {
    let help = r#"Usage: executable [OPTIONS] [SCHEMA]

Arguments:
  [SCHEMA]  The JSON Schema to validate with (i.e. schema.json)

Options:
  -i, --instance <INSTANCES>       A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)
  -d, --draft <DRAFT>              Enforce a specific JSON Schema draft [possible values: 4, 6, 7, 2019, 2020]
      --assert-format              Turn ON format validation
