                    // Remove in reverse order to maintain indices
                    for &i in props_indices.iter().rev() {
                        props_nodes.push(children.remove(i));
                    }
                    props_nodes.reverse();
                    // Need to get mutable reference to additionalProperties node (its index may have shifted after removals)
                    // Find again
                    if let Some(new_idx) = children.iter().position(|n| n.evaluation_path.ends_with("/additionalProperties")) {
                        // For each props node, we need to ensure its structure: currently each props node is /properties/a with details containing /properties/a/type
                        // That's already correct. We'll attach them as details of additionalProperties.
                        // But original's hierarchical had additionalProperties's details containing a node for /properties/a which itself has details for /properties/a/type.
                        // Our props_nodes already have that structure.
                        children[new_idx].details.extend(props_nodes);
                        // For valid case, additionalProperties had no error and was valid true; its dropped/annotations handling remains.
                    } else {
                        // Should not happen
                        for n in props_nodes {
                            children.push(n);
                        }
                    }
                }
            }
"""
    text = text.replace(marker, insertion + marker)
    print("patched hierarchical nesting")
else:
    print("marker not found")

p.write_text(text)
print("done")
